import {chromium} from 'playwright-core';
const b=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',args:['--disable-gpu']});const p=await b.newPage({viewport:{width:1728,height:1040}}); p.on('pageerror',e=>console.log('PAGEERROR',e.message));p.on('console',e=>{if(e.type()==='error')console.log('CONSOLE',e.text().slice(0,900))});await p.goto('http://127.0.0.1:5958/?desktop=1&engine=clothcraft',{waitUntil:'domcontentloaded'}); await p.waitForTimeout(3500);console.log('TITLE',await p.title()); console.log('BODY', (await p.locator('body').innerText()).slice(0,1900));console.log('BOARDS',await p.locator('.cc-board').count());await p.screenshot({path:'integrations/clothcraft/output/exo-pen-live-probe-20261028.png'});await b.close();
